import Purchases, { LOG_LEVEL } from "react-native-purchases";
import { Platform } from "react-native";

let configured = false;

export async function configureRevenueCat(userId?: string) {
  if (configured) return;
  const apiKey =
    Platform.OS === "ios"
      ? process.env.EXPO_PUBLIC_REVENUECAT_IOS_API_KEY!
      : process.env.EXPO_PUBLIC_REVENUECAT_ANDROID_API_KEY!;
  if (!apiKey) {
    console.warn("RevenueCat API key missing — skipping configure");
    return;
  }
  Purchases.setLogLevel(LOG_LEVEL.WARN);
  await Purchases.configure({ apiKey, appUserID: userId ?? null });
  configured = true;
}

export async function getOfferings() {
  return Purchases.getOfferings();
}

export async function purchasePackage(pkg: import("react-native-purchases").PurchasesPackage) {
  return Purchases.purchasePackage(pkg);
}

export async function hasEntitlement(id: string): Promise<boolean> {
  const info = await Purchases.getCustomerInfo();
  return info.entitlements.active[id] !== undefined;
}
